test('lateFee calculates fee for one day overdue', () => {
  const invoice = issueInvoice(
    createInvoice({
      customerId: 'C-001',
      issueDate: '2026-09-01',
      lines: [{ sku: 'DEV-HOUR', qty: 100 }],
      terms: 'NET30',
