    }).value,
    []
  ).value;

  const totals = invoiceTotals(invoice);

  // Half payment
  const partial = recordPayment(invoice, {
    amount: Math.floor(totals.total / 2),
    date: '2026-10-14',
  }).value;

  // Fee on 10 days overdue with half balance
  const result = lateFee(partial, '2026-10-11');

  // Remaining balance is half of original total
  const remainingDue = totals.total - Math.floor(totals.total / 2);
  const expectedFee = Math.round(remainingDue * 0.0004 * 10);
  assert.equal(result, expectedFee);
});

